import{z as i,x as p,o as t,c as A,q as r,j as o,D as e,d as s,s as n,S as l,b as B}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"大页","description":"","frontmatter":{"title":"大页","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/huge-pages.md","filePath":"cs/huge-pages.md","lastUpdated":1791063341000}'),d={name:"cs/huge-pages.md"};function h(m,a,c,T,u,D){const E=p("Mermaid");return t(),A("div",null,[a[2]||(a[2]=r('<h1 id="大页" tabindex="-1">大页 <a class="header-anchor" href="#大页" aria-label="Permalink to &quot;大页&quot;">​</a></h1><div class="epigraph"><p>用 2MB 或 1GB 的页覆盖同一段虚区间，TLB 里一条就能翻译许多 4K 页曾经占用的项。</p><footer>—— 据 Hennessy and Patterson, Computer Architecture: A Quantitative Approach；Navarro 等对超级页的整理</footer></div><p><a href="/cs/page-fault-path">上一课</a>按 4K 补页。<a href="/cs/tlb-translate">TLB</a> 条目有限：工作集一宽，翻译缺失比数据缺失更先爆。<a href="/cs/paging-vm">分页</a>允许页大小是 2 的幂，硬件用页表中间层的「叶子」指向大块物理内存。缺口是<strong>何时用大页</strong>：减 TLB 压力，而不把按需策略推倒重来。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>数据库缓冲池、虚拟机客户内存、科学计算数组，往往是连续 GB 级。若全用 4K，TLB 覆盖范围只有「项数 × 4K」。缺口不是新的 MMU 周期公式，而是：内核把若干连续物理页合成更大粒度，页表少走一层，TLB 以大页标签命中。代价是内碎片、分配失败时的回退，以及缺页一次要填的块变大。</p><p><span class="marginnote">直觉类比：TLB 像你桌面上的便签墙，每张便签只记一个「地址→位置」。4K 页是每 4 KB 的书都要占一张便签；大页是整排书架只贴一张标签。便签数量有限时，标签越粗，不查目录（页表）就能直接拿到的书越多。</span></p><p>本课不把每代 x86 的 PSE/PDPE 控制位写成手册。</p><p><span class="marginnote">透明大页（THP）在运行中折叠或拆开；显式 <code>mmap</code>/<code>hugetlbfs</code> 由程序申请。折叠需要连续物理内存，与后课 buddy 的高阶块相关。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>硬件：某级页表项置「大页」位，该项的物理基址对齐到 2MB/1GB，偏移字段变长。<a href="/cs/page-fault-path">缺页路径</a>若决定用大页，一次分配整块并填一项。用户可 <code>madvise</code> 提示；也可映射 hugetlbfs。失败则退回 4K，正确性不变，只是 TLB 覆盖变差。</p>',10)),(t(),o(l,null,{default:e(()=>[n(E,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20WS%5B%22%E5%A4%A7%E5%9D%97%E8%BF%9E%E7%BB%AD%E5%B7%A5%E4%BD%9C%E9%9B%86%22%5D%20--%3E%20HP%5B%22%E5%A4%A7%E9%A1%B5%3A%20%E4%B8%80%E9%A1%B9%E8%A6%86%E7%9B%96%22%5D%0A%20%20WS%20--%3E%20BASE%5B%224K%3A%20%E5%A4%9A%E9%A1%B9%E5%8D%A0%E6%BB%A1%20TLB%22%5D%0A%20%20HP%20--%3E%20TLB%5B%22TLB%20%E5%91%BD%E4%B8%AD%E7%8E%87%E5%8D%87%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=B("h2",{id:"机制",tabindex:"-1"},[s("机制 "),B("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=B("p",null,"大页把局部性从「页内」扩到「段内」：顺序扫描 2MB 不再换 512 条 4K 翻译。它不改变用户/内核分裂，也不取消按需——可以按大页粒度按需。与 Cache 行无关：大页不是把 Cache 变大，只是翻译变粗。",-1)),a[5]||(a[5]=B("p",null,"同一个地址，4K 页与大页的翻译各走多深？",-1)),(t(),o(l,null,{default:e(()=>[n(E,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20VA%5B%22%E5%90%8C%E4%B8%80%E8%99%9A%E6%8B%9F%E5%9C%B0%E5%9D%80%22%5D%20--%3E%20W4%5B%224K%20%E9%A1%B5%EF%BC%9APGD%E2%86%92PUD%E2%86%92PMD%E2%86%92PTE%20%E5%9B%9B%E7%BA%A7%E5%85%A8%E8%B5%B0%22%5D%0A%20%20VA%20--%3E%20W2%5B%222MB%20%E5%A4%A7%E9%A1%B5%EF%BC%9A%E5%88%B0%20PMD%20%E5%8D%B3%E5%8F%B6%EF%BC%8C%E5%B0%91%E8%B5%B0%E4%B8%80%E5%B1%82%22%5D%0A%20%20W4%20--%3E%20M4%5B%22TLB%20%E4%B8%80%E9%A1%B9%E5%8F%AA%E7%AE%A1%204KB%22%5D%0A%20%20W2%20--%3E%20M2%5B%22TLB%20%E4%B8%80%E9%A1%B9%E7%AE%A1%202MB%22%5D%0A%20%20M4%20--%3E%20T%5B%22%E5%91%BD%E4%B8%AD%E7%8E%87%E9%AB%98%E3%80%81%E9%81%8D%E5%8E%86%E6%9B%B4%E7%9F%AD%EF%BC%8C%E7%BF%BB%E8%AF%91%E6%88%90%E6%9C%AC%E6%9B%B4%E4%BD%8E%22%5D%0A%20%20M2%20--%3E%20T%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=r('<p><span class="marginnote">数字实例：一个典型 TLB 约有 1500 多项。按 4K 算，全部命中也只能覆盖约 6 MB 的工作集；换成 2MB 大页，同样项数覆盖约 3 GB。数据库缓冲池动辄几十 GB，这就是「翻译缺失比数据缺失先爆」的直观账。</span></p><p>多核上拆大页或改权限，要冲掉的 TLB 项更「宽」，下一课 shootdown 会更疼。本课只承认粒度变了。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不保证大页降低每一种负载：指针追逐、稀疏堆可能浪费物理内存。也不把设备 DMA 对齐问题写完。交换大页要拆或整块写出，实现复杂，主干留到 swap 课点名。不要在此重导多级页表。</p><p>后课默认：翻译项可以覆盖 2MB 级块。改页表后其他 CPU 的 TLB 如何作废，下一课 TLB shootdown。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>大页用更少 TLB 项覆盖连续工作集。</li><li>按需仍在，只是分配粒度变大；可回退 4K。</li><li>多核作废翻译是 shootdown 的缺口。</li><li>出处：Hennessy and Patterson, <em>CA:AQA</em>；Navarro et al., superpages；Tanenbaum <em>MOS</em>。</li></ul><p><span class="marginnote">常见误区：初学者容易以为「开大页必然更快、内存也省」。若访问模式稀疏（比如指针追逐散布在整个堆），2MB 页哪怕只用到几 KB 也独占整块物理内存——内碎片上去了，TLB 收益却没有。大页是连续大工作集的优化，不是无条件开关。</span></p>',8))])}const P=i(d,[["render",h]]);export{g as __pageData,P as default};
